import { readFileSync, existsSync, unlinkSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { resolveVault } from './lib/vault.mjs';
import { isGitRepo, commitPaths } from './lib/git.mjs';
import { dirtySet, deltaPaths } from './lib/op.mjs';
import { planAutoRefresh } from './lib/auto-refresh.mjs';
import { refreshIndex, readManifestFile } from './index-embed.mjs';
import { embed as ollamaEmbed, isAvailable, modelPresent, EMBED_MODEL } from './lib/embed.mjs';
import { isContent } from './lib/graph.mjs';
import { findWrappedLinks } from './lib/dewrap-links.mjs';

// See op-begin.mjs for why --untracked-files=all is load-bearing, not cosmetic.
function statusPorcelain(cwd) {
  return execFileSync('git', ['-c', 'core.quotePath=false', '--literal-pathspecs', 'status', '--porcelain', '--untracked-files=all'], {
    cwd,
    encoding: 'utf8',
    maxBuffer: 32 * 1024 * 1024,
  });
}

// How many local commits have not reached the upstream, so the gap between
// "committed" and "durable on other machines" stays visible without this
// script acting on it. Never pushes — same rule as purge: pushing is
// outward-facing and belongs to an explicit confirmation step, not a script
// that could run unattended. No upstream configured is tolerated, not an
// error: a freshly cloned or local-only vault has none.
function unpushedCount(cwd) {
  try {
    const out = execFileSync('git', ['rev-list', '--count', '@{u}..HEAD'], { cwd, encoding: 'utf8' }).trim();
    return Number(out);
  } catch {
    return null;
  }
}

// A hard-wrapped wikilink ([[Title\ncontinued]]) freshly introduced by the files THIS
// operation just committed, scanned from their current on-disk content -- scoped to
// exactly the paths that changed, not a full-vault rescan. This is visibility at the
// moment of commit, not a gate: op-commit has no existing "fail the commit" contract
// to extend safely, so nothing here blocks anything -- a found wrap is reported for
// scripts/repair-wrapped-links.mjs to fix afterward, the same reporting-not-blocking
// convention health.mjs already uses for defects it cannot repair automatically
// inline. See scripts/lib/dewrap-links.mjs.
function scanForWrappedLinks(vaultPath, paths) {
  const found = [];
  for (const p of paths) {
    if (!p.endsWith('.md') || !isContent(p)) continue;
    const abs = join(vaultPath, p);
    if (!existsSync(abs)) continue; // deleted as part of this operation — nothing to scan
    const text = readFileSync(abs, 'utf8');
    for (const w of findWrappedLinks(text)) found.push({ page: p, target: w.raw });
  }
  return found;
}

// Reads the token op-begin wrote, computes what THIS operation touched (dirty
// now minus dirty then), commits exactly that, and deletes the token whether
// or not there was anything to commit — an op that ran and found nothing to
// do, or ran against a vault that isn't a git repo, still finished; it should
// not leave scratch state behind for the next run to trip over.
export function commitOp(vaultPath, { op, title, token }) {
  // The token is joined straight into a path, and `unlinkSync` runs on it at the
  // end — so a token carrying `../` would both read and DELETE a file outside
  // .wiki-master/ops/. op-begin only ever emits hex, but this is invoked from
  // skill markdown where an agent assembles the command line, so the shape is
  // checked rather than assumed.
  if (!/^[0-9a-f]{8,64}$/.test(String(token))) {
    return { ok: false, reason: `malformed operation token "${token}" — expected the hex string op-begin printed` };
  }
  const tokenPath = join(vaultPath, '.wiki-master', 'ops', `${token}.json`);
  let record;
  try {
    record = JSON.parse(readFileSync(tokenPath, 'utf8'));
  } catch {
    // Covers both a missing token (readFileSync throws) and a corrupt one
    // (JSON.parse throws) — an unbracketed op must not look successful, so
    // both end up here rather than one silently producing an empty commit.
    return { ok: false, reason: `no such operation token "${token}" — was op-begin run first?` };
  }
  const before = new Set(record.dirty ?? []);

  let outcome;
  if (!isGitRepo(vaultPath)) {
    outcome = {
      ok: true, committed: false, reason: 'not a git repository',
      paths: [], before: [...before].sort(), unpushed: null,
    };
  } else {
    const after = dirtySet(statusPorcelain(vaultPath));
    const paths = deltaPaths(before, after);
    // No `if (paths.length)` guard here, deliberately: commitPaths already
    // returns { committed: false, reason: 'nothing to commit' } on an empty
    // array before it runs a single git command (lib/git.mjs), so a local
    // copy of that check would be untested dead weight, not a second layer
    // of defense — confirmed by mutation testing, not assumed.
    const result = commitPaths(vaultPath, paths, `${op}: ${title}`);
    outcome = {
      ok: true,
      committed: result.committed,
      sha: result.sha,
      reason: result.reason,
      paths,
      before: [...before].sort(),
      unpushed: result.committed ? unpushedCount(vaultPath) : null,
    };
  }
  outcome.wrappedLinks = scanForWrappedLinks(vaultPath, outcome.paths);
  unlinkSync(tokenPath);
  return outcome;
}

// Brings the semantic index back in line with the vault after an operation
// has changed it. This lives in op-commit rather than in each skill's
// markdown because op-commit is already the single choke point every mutating
// operation passes through -- one call here covers ingest, relink, purge and
// a filed query, instead of four places that can each be forgotten.
//
// Three properties hold it together:
//   - It runs AFTER the commit, so a refresh failure cannot reach it.
//   - Nothing it writes can pollute a commit: the index lives under the
//     vault's `.wiki-master/`, which every wiki-master vault gitignores
//     (scripts/init.mjs writes that line).
//   - It never throws and never sets an exit code, but it is never silent
//     either -- a silently stale index is precisely the failure mode the
//     0.11.0 search-health work exists to prevent.
export async function refreshAfterOp(vaultPath, {
  readManifestImpl = readManifestFile,
  isAvailableImpl = isAvailable,
  modelPresentImpl = modelPresent,
  refreshImpl = refreshIndex,
} = {}) {
  const dir = join(vaultPath, '.wiki-master');
  try {
    const indexPresent = Object.keys(readManifestImpl(dir)).length > 0;
    // Ollama is probed only when there is an index worth refreshing. These
    // are network round-trips and planAutoRefresh short-circuits on a
    // missing index before it ever consults them, so a vault that has never
    // built one pays nothing on every commit.
    const reachable = indexPresent ? await isAvailableImpl() : false;
    const present = reachable ? await modelPresentImpl() : false;
    const plan = planAutoRefresh({
      ollama: { reachable, modelPresent: present, model: EMBED_MODEL },
      indexPresent,
    });
    if (!plan.run) return { refreshed: false, notice: plan.notice };

    const r = await refreshImpl({ vaultPath, dir, embedFn: (text) => ollamaEmbed(text) });
    // Never silent about a PARTIAL build either. The index persisted and is
    // usable, but chunks are missing from it, and this notice is the only place
    // that surfaces -- reporting it as a clean build is the same silent-staleness
    // failure this function exists to prevent (#70).
    const failed = r.chunksFailed
      ? `, ${r.chunksFailed} chunk(s) FAILED to embed (retried next run)`
      : '';
    return {
      refreshed: true,
      notice: `semantic index: ${r.filesChanged} file(s) changed, ${r.chunksEmbedded} chunk(s) embedded, `
        + `${r.chunksTotal} total (${(r.elapsedMs / 1000).toFixed(1)}s)${failed}`,
    };
  } catch (err) {
    return { refreshed: false, notice: `semantic index not refreshed — ${err.message}` };
  }
}

export async function main(argv, refreshDeps) {
  const get = (flag) => {
    const i = argv.indexOf(flag);
    return i >= 0 ? argv[i + 1] : undefined;
  };
  const op = get('--op');
  const title = get('--title');
  const token = get('--since');
  if (!op || !title || !token) {
    console.error('usage: node scripts/op-commit.mjs --op <op> --title "<title>" --since <token>');
    process.exitCode = 1;
    return;
  }
  const { path: vaultPath } = resolveVault();
  const r = commitOp(vaultPath, { op, title, token });

  if (!r.ok) {
    console.error(`op-commit: ${r.reason}`);
    process.exitCode = 1;
    return;
  }
  // A chain rather than early returns: a vault that is not a git repo still
  // has an index that goes stale, so every branch has to reach the refresh
  // at the end of this function.
  if (r.reason === 'not a git repository') {
    console.log('op-commit: this vault is not a git repository — nothing to commit.');
  } else if (r.committed) {
    console.log(`committed ${r.sha.slice(0, 7)}: ${r.paths.length} file(s)`);
    for (const p of r.paths) console.log(`  ${p}`);
  } else {
    console.log(`op-commit: "${op}" made no changes — nothing to commit.`);
  }
  if (r.before.length) {
    console.log(`left alone (already dirty before this operation, not part of it): ${r.before.length} file(s)`);
    for (const p of r.before) console.log(`  ${p}`);
  }
  if (typeof r.unpushed === 'number' && r.unpushed > 0) {
    console.log(`${r.unpushed} commit(s) unpushed. Run \`git push\` from the vault to sync.`);
  }
  if (r.wrappedLinks.length) {
    console.log(`⚠ ${r.wrappedLinks.length} hard-wrapped wikilink(s) in the files just committed — run \`node scripts/repair-wrapped-links.mjs --apply\`:`);
    for (const w of r.wrappedLinks) console.log(`  ${w.page}`);
  }

  const { notice } = await refreshAfterOp(vaultPath, refreshDeps);
  if (notice) console.log(notice);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2));
}

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { resolveVault } from './lib/vault.mjs';
import { embed as ollamaEmbed, isAvailable, cosine } from './lib/embed.mjs';
import { hash, loadCache, saveCache } from './lib/embed-cache.mjs';
import { buildGraph, buildNameIndex, evidencePaths } from './lib/graph.mjs';
import { parseNote } from './lib/note.mjs';
import { chunkMarkdown } from './lib/chunk.mjs';

const DEFAULT_THRESHOLD = 0.5;
const MAX_CHARS = 1200;
const MAX_CHUNKS = 8;
const MAX_SOURCES = 8;

function normalizeVector(vector) {
  if (!Array.isArray(vector) || !vector.length || vector.some(n => !Number.isFinite(n))) throw new Error('invalid embedding vector');
  const norm = Math.hypot(...vector);
  if (!norm) throw new Error('zero embedding vector');
  return vector.map(n => n / norm);
}

function sample(items, limit) {
  if (items.length <= limit) return items;
  return Array.from({ length: limit }, (_, i) => items[Math.round(i * (items.length - 1) / (limit - 1))]);
}

function documentChunks(text) {
  if (text.length <= MAX_CHARS) return [text];
  // Reuse structural splitting; bound unusually long headings/prefixes too.
  // Nothing is discarded here: sampling is separate and reported explicitly.
  return chunkMarkdown(text, { title: '', targetChars: 600, overlapChars: 75 }).flatMap(chunk => {
    const pieces = [];
    for (let i = 0; i < chunk.text.length; i += MAX_CHARS) pieces.push(chunk.text.slice(i, i + MAX_CHARS));
    return pieces;
  });
}

async function documentVector(text, embedFn) {
  const chunks = documentChunks(text);
  const chosen = sample(chunks, MAX_CHUNKS);
  const vectors = [];
  for (const chunk of chosen) vectors.push(normalizeVector(await embedFn(chunk)));
  if (vectors.some(v => v.length !== vectors[0].length)) throw new Error('embedding dimensions differ');
  return { vector: normalizeVector(centroid(vectors)), coverage: { total: chunks.length, sampled: chosen.length } };
}

function centroid(vecs) {
  const n = vecs.length;
  const out = new Array(vecs[0].length).fill(0);
  for (const v of vecs) for (let i = 0; i < v.length; i++) out[i] += v[i] / n;
  return out;
}

export async function computeDrift(pages, { embedFn, threshold = DEFAULT_THRESHOLD, limit, coverage = false, unavailable = false } = {}) {
  if (limit !== undefined && (!Number.isInteger(limit) || limit < 1)) throw new Error('limit must be a positive integer');
  const drifted = [], evaluated = [], failed = [], skippedPages = [];
  const eligible = pages.filter(page => page.sources?.length).length;
  let attempted = 0;
  for (const page of pages) {
    const reason = !page.sources?.length ? 'no reachable readable evidence'
      : coverage ? 'coverage only' : unavailable ? 'embedder unavailable'
      : attempted >= (limit ?? Infinity) ? 'limit' : null;
    if (reason) { skippedPages.push({ path: page.path, reason }); continue; }
    attempted++;
    // One un-embeddable page (or raw source -- typically the longest content
    // in the vault, so likeliest to exceed the embedding model's context
    // window) must not take the whole drift run down. Recorded, never silent.
    try {
      const pageResult = await documentVector(page.body, embedFn);
      const srcVecs = [];
      const documents = [];
      const chosenSources = sample(page.sources, MAX_SOURCES);
      for (const s of chosenSources) {
        const result = await documentVector(s.content, embedFn);
        srcVecs.push(result.vector);
        documents.push({ path: s.path, ...result.coverage });
      }
      if (srcVecs.some(v => v.length !== pageResult.vector.length)) throw new Error('embedding dimensions differ');
      const sim = cosine(pageResult.vector, normalizeVector(centroid(srcVecs)));
      const sampling = { page: pageResult.coverage, sources: { total: page.sources.length, sampled: chosenSources.length, documents },
        partial: pageResult.coverage.sampled < pageResult.coverage.total || chosenSources.length < page.sources.length || documents.some(d => d.sampled < d.total) };
      evaluated.push({ path: page.path, sim, sampling });
      if (sim < threshold) drifted.push({ path: page.path, sim });
    } catch (err) {
      failed.push({ path: page.path, error: err.message });
    }
  }
  return { drifted, evaluated, failed, skipped: coverage || unavailable, coverage, skippedPages,
    counts: { total: pages.length, eligible, ineligible: pages.length - eligible,
      evaluated: evaluated.length, failed: failed.length, skipped: skippedPages.length,
      skippedEligible: eligible - evaluated.length - failed.length } };
}

export function collectDriftPages(vaultPath) {
  const { pages } = buildGraph(vaultPath);
  const byName = buildNameIndex(pages);
  const byPath = new Map(pages.map(page => [page.path, page]));
  return pages.filter(page => /^wiki\/(concepts|syntheses)\/.+\.md$/.test(page.path)).map(page => {
    const evidence = evidencePaths(page, byName, byPath).filter(path => path.endsWith('.md'));
    const raw = evidence.filter(path => path.startsWith('raw/'));
    const sources = (raw.length ? raw : evidence).map(path => ({ path, content: parseNote(readFileSync(join(vaultPath, path), 'utf8')).body }));
    return { path: page.path, body: parseNote(readFileSync(join(vaultPath, page.path), 'utf8')).body, sources };
  });
}

export function formatDriftReport(result) {
  const c = result.counts;
  const lines = [`drift: total ${c.total} · eligible ${c.eligible} · ineligible ${c.ineligible} · evaluated ${c.evaluated} · failed ${c.failed} · skipped ${c.skipped} (${c.skippedEligible} eligible)`];
  if (result.coverage) lines.push('drift: coverage only; no embeddings or factual verification performed');
  else if (!c.evaluated) lines.push('drift: no pages evaluated; no clean verdict is available');
  else if (!result.drifted.length) lines.push('drift: no evaluated pages diverged from their sources');
  for (const d of result.drifted) lines.push(`  drift ${d.sim.toFixed(2)}  ${d.path}`);
  for (const e of result.evaluated) {
    const s = e.sampling;
    lines.push(`  sampled ${s.page.sampled}/${s.page.total} page chunks; ${s.sources.sampled}/${s.sources.total} evidence documents, ${s.sources.documents.reduce((n, d) => n + d.sampled, 0)}/${s.sources.documents.reduce((n, d) => n + d.total, 0)} chunks in those documents${s.partial ? ' (partial coverage)' : ''}  ${e.path}`);
  }
  for (const f of result.failed) lines.push(`  drift: could not evaluate ${f.path} (${f.error})`);
  lines.push('Semantic similarity is a review signal, not factual verification or claim entailment.');
  return lines;
}

// Hash-keyed embedding cache (loadCache/saveCache/hash) now lives in
// lib/embed-cache.mjs, shared with search.mjs.

export async function main(argv = []) {
  const options = {};
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--coverage') options.coverage = true;
    else if (argv[i] === '--json') options.json = true;
    else if (argv[i] === '--limit' || argv[i].startsWith('--limit=')) {
      const value = argv[i] === '--limit' ? argv[++i] : argv[i].slice('--limit='.length);
      if (!/^\d+$/.test(value ?? '') || Number(value) < 1 || !Number.isSafeInteger(Number(value))) throw new Error('--limit must be a positive integer');
      options.limit = Number(value);
    } else throw new Error(`unknown argument: ${argv[i]}`);
  }
  const { path: vaultPath } = resolveVault();
  const pages = collectDriftPages(vaultPath);
  const unavailable = !options.coverage && !(await isAvailable());
  if (options.coverage || unavailable) {
    const r = await computeDrift(pages, { ...options, unavailable });
    if (options.json) console.log(JSON.stringify(r));
    else for (const line of formatDriftReport(r)) console.log(line);
    return r;
  }
  const cacheDir = join(vaultPath, '.wiki-master');
  const cache = loadCache(cacheDir);
  const cachedEmbed = async (text) => {
    const k = hash(text);
    if (cache[k]) return cache[k];
    const v = await ollamaEmbed(text);
    cache[k] = v;
    return v;
  };
  const r = await computeDrift(pages, { ...options, embedFn: cachedEmbed });
  saveCache(cacheDir, cache);
  if (options.json) console.log(JSON.stringify(r));
  else for (const line of formatDriftReport(r)) console.log(line);
  return r;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2)).catch(error => { console.error(error.message); process.exitCode = 1; });
}

import { mkdirSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { resolveVault } from './lib/vault.mjs';
import { isGitRepo } from './lib/git.mjs';
import { dirtySet } from './lib/op.mjs';

// Same flags scripts/lib/git.mjs's internal git() wrapper uses on every call:
// core.quotePath=false keeps non-ASCII bytes literal (dirtySet only strips the
// surrounding quote pair, it does not decode octal escapes); --literal-pathspecs
// is a no-op for `status` but kept for consistency with the rest of this codebase.
//
// --untracked-files=all is NOT cosmetic here: by default git collapses an
// entirely-untracked directory into one line (`?? wiki/`) instead of listing
// the files inside it. git.mjs's uncommittedElsewhere doesn't need this flag
// because it is display-only, but this snapshot feeds deltaPaths, whose
// output becomes commitPaths's pathspec list — `wiki/` as a literal path
// stages the directory's contents fine (git add honors the trailing slash)
// but then fails commitPaths's own "did OUR paths end up staged" check
// (`git diff --cached --name-only` lists the individual files, never the
// directory), which made commitPaths report "nothing to commit" while having
// silently left real files staged. Reproduced against a fresh untracked
// `wiki/` dir with two new files before this flag was added.
function statusPorcelain(cwd) {
  return execFileSync('git', ['-c', 'core.quotePath=false', '--literal-pathspecs', 'status', '--porcelain', '--untracked-files=all'], {
    cwd,
    encoding: 'utf8',
    maxBuffer: 32 * 1024 * 1024,
  });
}

// Snapshots what was ALREADY dirty before this operation starts, so op-commit
// can later exclude it from the operation's own commit — the property that
// makes this safe where `git add -A` is not. A vault that is not a git
// repository has nothing to snapshot; op-commit handles that case when it
// tries to commit, not here, so op-begin still succeeds and a skill can still
// bracket the operation.
export function beginOp(vaultPath, op) {
  const dirty = isGitRepo(vaultPath) ? [...dirtySet(statusPorcelain(vaultPath))] : [];
  const token = randomBytes(8).toString('hex');
  const opsDir = join(vaultPath, '.wiki-master', 'ops');
  mkdirSync(opsDir, { recursive: true });
  writeFileSync(
    join(opsDir, `${token}.json`),
    `${JSON.stringify({ op, startedAt: new Date().toISOString(), dirty }, null, 2)}\n`
  );
  return token;
}

export function main(argv) {
  const get = (flag) => {
    const i = argv.indexOf(flag);
    return i >= 0 ? argv[i + 1] : undefined;
  };
  const op = get('--op');
  if (!op) {
    console.error('usage: node scripts/op-begin.mjs --op <op>');
    process.exitCode = 1;
    return;
  }
  const { path: vaultPath } = resolveVault();
  // Only the token on stdout — a skill captures it with $(...); anything else
  // printed here would get captured right along with it.
  console.log(beginOp(vaultPath, op));
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2));
}
